for y in range(6):
    row = {}
    for x in range(6):
        val = f(x, y)
        parity = "Odd" if val % 2 != 0 else "Even"
        row[(x, y)] = (val, parity)
        print(f"f({x}, {y}) = {val} ({parity})", end=" | ")
    print("\n" + "-"*30)

