def f(x, y):
    # f(x, y) = T_{x+y} + x
    S = x + y
    T_S = S * (S + 1) // 2
    return T_S + x

N = 0
limit = 16
for x in range(limit):
    for y in range(limit):
        if f(x, y) % 2 != 0:
